<template>
  <div class="card shadow-sm border-0 rounded-3"><div class="card-header bg-success text-white py-3"><h5 class="mb-0">Kardex de ingresos</h5></div><div class="card-body"><div class="row g-2 mb-3"><div class="col-md-4"><input v-model="filtros.buscar" class="form-control" placeholder="Producto, concentración o código LINAME"></div><div class="col-md-3"><input v-model="filtros.procedencia" class="form-control" placeholder="Procedencia / proveedor"></div><div class="col-md-2"><input v-model="filtros.fecha_desde" type="date" class="form-control"></div><div class="col-md-2"><input v-model="filtros.fecha_hasta" type="date" class="form-control"></div><div class="col-md-1"><button class="btn btn-primary w-100" @click="cargar">Buscar</button></div></div><div class="table-responsive"><table class="table table-sm table-hover align-middle"><thead class="table-light"><tr><th>Fecha</th><th>Nota / remisión</th><th>Partida</th><th>LINAME</th><th>Producto</th><th>Procedencia</th><th>Lote</th><th>Vence</th><th class="text-end">Cant.</th><th class="text-end">P. unit.</th><th class="text-end">Total</th></tr></thead><tbody><tr v-if="cargando"><td colspan="11" class="text-center py-4">Cargando…</td></tr><tr v-else-if="filas.length === 0"><td colspan="11" class="text-center py-4 text-muted">No se encontraron ingresos con esos filtros.</td></tr><tr v-for="fila in filas" :key="fila.id"><td>{{ fecha(fila.ingreso?.fecha_ingreso) }}</td><td>{{ fila.ingreso?.numero_nota }}<small v-if="fila.ingreso?.numero_remision" class="d-block text-muted">Rem. {{ fila.ingreso.numero_remision }}</small></td><td>{{ fila.medicamento?.partida_presupuestaria?.codigo }}</td><td>{{ fila.medicamento?.codigo }}</td><td>{{ fila.medicamento?.nombre }}<small v-if="fila.medicamento?.forma_farmaceutica" class="d-block text-muted">{{ fila.medicamento.forma_farmaceutica }}</small></td><td>{{ fila.proveedor?.nombre }}</td><td>{{ fila.codigo_lote }}</td><td>{{ fecha(fila.fecha_vencimiento) }}</td><td class="text-end">{{ fila.cantidad_inicial }}</td><td class="text-end">{{ moneda(fila.precio_unitario) }}</td><td class="text-end fw-bold">{{ moneda(fila.importe_total) }}</td></tr></tbody></table></div></div></div>
</template>
<script setup>
import axios from 'axios'; import { onMounted, reactive, ref } from 'vue';
const filas = ref([]), cargando = ref(false), filtros = reactive({ buscar: '', procedencia: '', fecha_desde: '', fecha_hasta: '' }); const moneda = n => new Intl.NumberFormat('es-BO', { style: 'currency', currency: 'BOB' }).format(n || 0); const fecha = f => f ? new Date(`${f}T00:00:00`).toLocaleDateString('es-BO') : '—'; const cargar = async () => { cargando.value = true; try { const { data } = await axios.get('api/kardex', { params: filtros }); filas.value = data; } finally { cargando.value = false; } }; onMounted(cargar);
</script>
